begin;
insert into auth.users(id,email)values('a1000000-1111-4000-8000-000000000001','maintenance-owner@example.invalid'),('a1000000-1111-4000-8000-000000000002','maintenance-member@example.invalid');
insert into public.workspaces(id,name,slug)values('a2000000-1111-4000-8000-000000000001','Maintenance Synthetic','maintenance-synthetic');
insert into public.workspace_members(workspace_id,user_id,role)values('a2000000-1111-4000-8000-000000000001','a1000000-1111-4000-8000-000000000001','owner'),('a2000000-1111-4000-8000-000000000001','a1000000-1111-4000-8000-000000000002','member');
insert into public.customers(id,workspace_id,account_kind,legal_name)values('a3000000-1111-4000-8000-000000000001','a2000000-1111-4000-8000-000000000001','legal_entity','Maintenance Synthetic');
insert into public.documents(id,workspace_id,customer_id,document_kind,file_name,media_type,size_bytes,storage_path,status)values('a4000000-1111-4000-8000-000000000001','a2000000-1111-4000-8000-000000000001','a3000000-1111-4000-8000-000000000001','general','Synthetic.pdf','application/pdf',10,'a2000000-1111-4000-8000-000000000001/documents/a4000000-1111-4000-8000-000000000001/a5000000-1111-4000-8000-000000000001','active'),('a4000000-1111-4000-8000-000000000002','a2000000-1111-4000-8000-000000000001','a3000000-1111-4000-8000-000000000001','general','Synthetic pending.pdf','application/pdf',10,'a2000000-1111-4000-8000-000000000001/documents/a4000000-1111-4000-8000-000000000002/a5000000-1111-4000-8000-000000000002','pending');
insert into public.document_download_tickets(id,document_id,workspace_id,actor_id)values('a6000000-1111-4000-8000-000000000001','a4000000-1111-4000-8000-000000000001','a2000000-1111-4000-8000-000000000001','a1000000-1111-4000-8000-000000000001');
insert into public.document_upload_intents(document_id,workspace_id,actor_id,object_ref,created_at,expires_at)values('a4000000-1111-4000-8000-000000000002','a2000000-1111-4000-8000-000000000001','a1000000-1111-4000-8000-000000000001','a5000000-1111-4000-8000-000000000002',statement_timestamp()-interval '26 hours',statement_timestamp()-interval '25 hours');
insert into public.document_integrity_verifiers(key_id,key_bytes)values('a7000000-1111-4000-8000-000000000001',extensions.gen_random_bytes(32));
create function pg_temp.assert_m(ok boolean)returns void language plpgsql as $$begin if ok is not true then raise exception 'maintenance_assertion';end if;end$$;
create function pg_temp.deny_m(q text,c text)returns void language plpgsql as $$begin begin execute q;exception when others then if sqlstate=c then return;end if;raise;end;raise exception 'expected_maintenance_denial';end$$;
-- Native proof checks witness authentication/scope; actual bytes are independently measured in real Storage/Next fixture.
do $$declare ts bigint;key bytea;payload text;w jsonb;begin ts:=floor(extract(epoch from statement_timestamp())*1000)::bigint;select key_bytes into key from public.document_integrity_verifiers where key_id='a7000000-1111-4000-8000-000000000001';
payload:='document.integrity.v1|a2000000-1111-4000-8000-000000000001|a1000000-1111-4000-8000-000000000001|a8000000-1111-4000-8000-000000000001|a4000000-1111-4000-8000-000000000001|1|a6000000-1111-4000-8000-000000000001|a5000000-1111-4000-8000-000000000001|10|application/pdf|'||repeat('c',64)||'|'||ts::text||'|not_scanned';
w:=jsonb_build_object('key_id','a7000000-1111-4000-8000-000000000001','object_ref','a5000000-1111-4000-8000-000000000001','size_bytes',10,'media_type','application/pdf','sha256',repeat('c',64),'measured_at',ts,'scan_status','not_scanned','mac',encode(extensions.hmac(convert_to(payload,'UTF8'),key,'sha256'),'hex'));perform set_config('test.maintenance_witness',w::text,true);end$$;
set local role authenticated;select set_config('request.jwt.claim.sub','a1000000-1111-4000-8000-000000000001',true);
select pg_temp.assert_m(public.document_integrity_v1_verify('a2000000-1111-4000-8000-000000000001','{"command_id":"a8000000-1111-4000-8000-000000000001","id":"a4000000-1111-4000-8000-000000000001","expected_version":1,"ticket_id":"a6000000-1111-4000-8000-000000000001"}',current_setting('test.maintenance_witness')::jsonb)->>'version'='2');
select pg_temp.assert_m(public.document_integrity_v1_verify('a2000000-1111-4000-8000-000000000001','{"command_id":"a8000000-1111-4000-8000-000000000001","id":"a4000000-1111-4000-8000-000000000001","expected_version":1,"ticket_id":"a6000000-1111-4000-8000-000000000001"}',current_setting('test.maintenance_witness')::jsonb)->>'version'='2');
select pg_temp.deny_m($q$select public.document_integrity_v1_verify('a2000000-1111-4000-8000-000000000001','{"command_id":"a8000000-1111-4000-8000-000000000001","id":"a4000000-1111-4000-8000-000000000001","expected_version":1,"ticket_id":"a6000000-1111-4000-8000-000000000001"}',jsonb_set(current_setting('test.maintenance_witness')::jsonb,'{mac}',to_jsonb(repeat('0',64))))$q$,'42501');
select pg_temp.assert_m(jsonb_array_length(public.document_cleanup_v1_expired_list('a2000000-1111-4000-8000-000000000001','{}')->'items')=1);
select pg_temp.assert_m(public.document_cleanup_v1_claim('a2000000-1111-4000-8000-000000000001','{"command_id":"a8000000-1111-4000-8000-000000000002","id":"a4000000-1111-4000-8000-000000000002","expected_version":1}')->>'version'='2');
select pg_temp.assert_m(public.document_cleanup_v1_deletable('a2000000-1111-4000-8000-000000000001/documents/a4000000-1111-4000-8000-000000000002/a5000000-1111-4000-8000-000000000002'));
select pg_temp.deny_m($q$select public.document_cleanup_v1_claim('a2000000-1111-4000-8000-000000000001','{"command_id":"a8000000-1111-4000-8000-000000000003","id":"a4000000-1111-4000-8000-000000000001","expected_version":2}')$q$,'42501');
select pg_temp.assert_m(public.document_cleanup_v1_finish('a2000000-1111-4000-8000-000000000001','{"command_id":"a8000000-1111-4000-8000-000000000004","id":"a4000000-1111-4000-8000-000000000002","expected_version":2}')->>'status'='archived');
select pg_temp.assert_m(public.document_cleanup_v1_prepare_finish('a2000000-1111-4000-8000-000000000001','{"command_id":"a8000000-1111-4000-8000-000000000004","id":"a4000000-1111-4000-8000-000000000002","expected_version":2}')->'receipt'->>'version'='3');
reset role;select pg_temp.assert_m((select count(*)=1 from public.document_content_integrity));select pg_temp.deny_m($q$update public.document_content_integrity set sha256=repeat('0',64)$q$,'55000');
set local role authenticated;select set_config('request.jwt.claim.sub','a1000000-1111-4000-8000-000000000002',true);select pg_temp.deny_m($q$select public.document_cleanup_v1_expired_list('a2000000-1111-4000-8000-000000000001','{}')$q$,'42501');
reset role;rollback;
